def get_javascript():
    return r"""<script>
(()=>{const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),o=$("#mp-auth-overlay"),m=$("#auth-msg");function open(mode="login"){o.classList.add("open");tab(mode)}function close(){o.classList.remove("open")}function tab(mode){$("#login-form").hidden=mode!=="login";$("#signup-form").hidden=mode!=="signup";$("#otp-form").hidden=mode!=="otp";$("#auth-title").textContent=mode==="signup"?"Create your account":mode==="otp"?"Verify with OTP":"Welcome back";$$("[data-auth-tab]").forEach(b=>b.style.background=b.dataset.authTab===mode?"#fff":"transparent")}$$("[data-open-auth]").forEach(b=>b.onclick=()=>open(b.dataset.openAuth));$$("[data-close-auth]").forEach(b=>b.onclick=close);$$("[data-auth-tab]").forEach(b=>b.onclick=()=>tab(b.dataset.authTab));$("[data-open-otp]")?.addEventListener("click",()=>tab("otp"));async function post(url,body){const r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.detail||"Request failed");return d}$("#login-form")?.addEventListener("submit",async e=>{e.preventDefault();try{const d=await post("/auth/login",{identifier:$("#login-id").value,password:$("#login-pass").value});m.textContent=d.message;setTimeout(close,500)}catch(x){m.textContent=x.message}});$("#signup-form")?.addEventListener("submit",async e=>{e.preventDefault();try{const d=await post("/auth/signup",{name:$("#signup-name").value,email:$("#signup-email").value,phone:$("#signup-phone").value,password:$("#signup-pass").value});m.textContent=d.message;$("#otp-id").value=$("#signup-email").value;tab("otp")}catch(x){m.textContent=x.message}});$("#send-otp")?.addEventListener("click",async()=>{try{const d=await post("/auth/send-otp",{identifier:$("#otp-id").value});m.textContent=d.message}catch(x){m.textContent=x.message}});$("#logout-btn")?.addEventListener("click",async()=>{try{const d=await post("/auth/logout",{});m.textContent=d.message;close()}catch(x){m.textContent=x.message}});$("#otp-form")?.addEventListener("submit",async e=>{e.preventDefault();try{const d=await post("/auth/verify-otp",{identifier:$("#otp-id").value,otp:$("#otp-code").value});m.textContent=d.message;setTimeout(close,500)}catch(x){m.textContent=x.message}})})();
</script>"""
__all__=["get_javascript"]
